import React, { useEffect, useRef, useState } from 'react';
import {
  AlertCircle,
  ArrowRight,
  CheckCircle2,
  FileUp,
  Loader2,
  LockKeyhole,
  MessageCircle,
  Send,
  ShieldCheck,
  Sparkles,
  X,
} from 'lucide-react';
import { AnimatePresence, motion } from 'motion/react';
import { useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { SEO } from '../components/SEO';
import { PublicDmHistoryRail } from '../components/public/PublicDmHistoryRail';
import { supabase, supabasePublishableKey, supabaseUrl } from '../lib/supabase';
import {
  forgetPublicDm,
  loadPublicDmHistory,
  publicDmConversationPath,
  rememberPublicDm,
  type RememberedPublicDm,
} from '../lib/publicDmHistory';

declare global {
  interface Window {
    turnstile?: {
      render: (element: HTMLElement, options: Record<string, unknown>) => string;
      remove: (widgetId: string) => void;
    };
  }
}

type PublicConfig = {
  username: string;
  displayName: string;
  avatarUrl: string | null;
  companyName: string | null;
  title: string;
  description: string;
  logoUrl: string | null;
  accentColor: string;
  presetTopics: string[];
  thankYouMessage: string;
  requirements: {
    name: boolean;
    email: boolean;
    subject: boolean;
    company: 'hidden' | 'optional' | 'required';
    website: boolean;
    attachments: boolean;
    maximumLength: number;
    customQuestions: Array<{ id: string; label: string; required: boolean }>;
  };
  consentMessage: string;
  captcha: { enabled: boolean; siteKey: string; available: boolean };
};

type ConversationMessage = {
  id: string;
  senderType: 'guest' | 'owner';
  content: string;
  createdAt: string;
};

type PublicConversation = {
  submissionId: string;
  subject: string | null;
  guestName: string | null;
  initialMessage: string;
  createdAt: string;
  status: string;
  messages: ConversationMessage[];
};

const inputClass = 'w-full rounded-[18px] border border-white/10 bg-white/[0.055] px-4 py-3.5 text-[15px] text-white outline-none transition placeholder:text-white/25 hover:border-white/15 focus:border-white/30 focus:bg-white/[0.075] focus:ring-4 focus:ring-white/[0.035]';

export const PublicDmPage = () => {
  const { username = '' } = useParams<{ username: string }>();
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const [config, setConfig] = useState<PublicConfig | null>(null);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [requiresAuthentication, setRequiresAuthentication] = useState(false);
  const [conversation, setConversation] = useState<PublicConversation | null>(null);
  const [threadReply, setThreadReply] = useState('');
  const [sendingReply, setSendingReply] = useState(false);
  const [receiptStatus, setReceiptStatus] = useState<{ status: string; readAt: string | null; createdAt: string } | null>(null);
  const [message, setMessage] = useState('');
  const [topic, setTopic] = useState('');
  const [files, setFiles] = useState<File[]>([]);
  const [captchaToken, setCaptchaToken] = useState('');
  const [customAnswers, setCustomAnswers] = useState<Record<string, string>>({});
  const [rememberedConversations, setRememberedConversations] = useState<RememberedPublicDm[]>(() => loadPublicDmHistory());
  const captchaContainerRef = useRef<HTMLDivElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const secretKey = searchParams.get('key') || '';
  const receiptId = searchParams.get('receipt') || '';
  const receiptToken = searchParams.get('token') || '';
  const conversationId = searchParams.get('conversation') || '';
  const endpoint = `${supabaseUrl.replace(/\/$/, '')}/functions/v1/public-dm?username=${encodeURIComponent(username)}${secretKey ? `&key=${encodeURIComponent(secretKey)}` : ''}${receiptId ? `&receipt=${encodeURIComponent(receiptId)}` : ''}${conversationId ? `&conversation=${encodeURIComponent(conversationId)}` : ''}${receiptToken ? `&token=${encodeURIComponent(receiptToken)}` : ''}`;

  const authHeaders = async () => {
    const { data: { session } } = await supabase.auth.getSession();
    return {
      apikey: supabasePublishableKey,
      Authorization: `Bearer ${session?.access_token || supabasePublishableKey}`,
    };
  };

  useEffect(() => {
    let active = true;
    const load = async () => {
      setLoading(true);
      setError('');
      const response = await fetch(endpoint, { headers: await authHeaders() });
      const result = await response.json().catch(() => ({}));
      if (!active) return;
      if (!response.ok) {
        if (conversationId && receiptToken) {
          setRememberedConversations(forgetPublicDm(username, conversationId));
          navigate(`/pd/${encodeURIComponent(username)}`, { replace: true });
          return;
        }
        setLoading(false);
        setRequiresAuthentication(Boolean(result.requiresAuthentication));
        setError(result.error || 'This public inbox is not available.');
        return;
      }
      setLoading(false);
      if (result.receipt) {
        setReceiptStatus(result.receipt);
        return;
      }
      setConfig(result.config);
      setConversation(result.conversation || null);
      setTopic(result.config?.presetTopics?.[0] || '');
    };
    void load();
    return () => { active = false; };
  }, [username, secretKey, receiptId, receiptToken, conversationId]);

  useEffect(() => {
    if (!conversationId || !receiptToken) return;
    let active = true;
    const refresh = async () => {
      const response = await fetch(endpoint, { headers: await authHeaders(), cache: 'no-store' });
      const result = await response.json().catch(() => ({}));
      if (active && response.ok && result.conversation) setConversation(result.conversation);
    };
    const interval = window.setInterval(() => void refresh(), 3000);
    return () => {
      active = false;
      window.clearInterval(interval);
    };
  }, [conversationId, receiptToken, endpoint]);

  useEffect(() => {
    if (!config || !conversation || !conversationId || !receiptToken) return;
    const latestMessage = conversation.messages.at(-1);
    setRememberedConversations(rememberPublicDm({
      username: config.username || username,
      submissionId: conversation.submissionId,
      token: receiptToken,
      recipientName: config.displayName,
      conversationTitle: conversation.subject || config.title,
      avatarUrl: config.logoUrl || config.avatarUrl,
      accentColor: config.accentColor,
      updatedAt: latestMessage?.createdAt || conversation.createdAt,
    }));
  }, [
    config?.username,
    config?.displayName,
    config?.logoUrl,
    config?.avatarUrl,
    config?.accentColor,
    config?.title,
    conversation?.submissionId,
    conversation?.subject,
    conversation?.createdAt,
    conversation?.messages.at(-1)?.createdAt,
    conversationId,
    receiptToken,
    username,
  ]);

  useEffect(() => {
    if (!conversation) return;
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
  }, [conversation?.submissionId, conversation?.messages.length]);

  useEffect(() => {
    if (!config?.captcha.enabled || !config.captcha.available || !config.captcha.siteKey) return;
    let widgetId = '';
    let cancelled = false;
    const render = () => {
      if (cancelled || !window.turnstile || !captchaContainerRef.current || widgetId) return;
      widgetId = window.turnstile.render(captchaContainerRef.current, {
        sitekey: config.captcha.siteKey,
        theme: 'dark',
        callback: (token: string) => setCaptchaToken(token),
        'expired-callback': () => setCaptchaToken(''),
        'error-callback': () => setCaptchaToken(''),
      });
    };
    if (window.turnstile) {
      render();
    } else {
      const existing = document.querySelector<HTMLScriptElement>('script[data-wersee-turnstile]');
      if (existing) {
        existing.addEventListener('load', render, { once: true });
      } else {
        const script = document.createElement('script');
        script.src = 'https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';
        script.async = true;
        script.defer = true;
        script.dataset.werseeTurnstile = 'true';
        script.addEventListener('load', render, { once: true });
        document.head.appendChild(script);
      }
    }
    return () => {
      cancelled = true;
      if (widgetId && window.turnstile) window.turnstile.remove(widgetId);
    };
  }, [config?.captcha.enabled, config?.captcha.siteKey]);

  const addFiles = (incoming: FileList | null) => {
    if (!incoming) return;
    setFiles(Array.from(incoming).slice(0, 3));
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!config || submitting) return;
    setSubmitting(true);
    setError('');
    const form = new FormData(event.currentTarget);
    form.set('message', message);
    form.set('topic', topic);
    form.set('consent', String(form.get('consent') === 'on'));
    form.set('captchaToken', captchaToken);
    form.set('customAnswers', JSON.stringify(customAnswers));
    form.delete('attachments');
    files.forEach((file) => form.append('attachments', file));

    const response = await fetch(endpoint, {
      method: 'POST',
      headers: await authHeaders(),
      body: form,
    });
    const result = await response.json().catch(() => ({}));
    setSubmitting(false);
    if (!response.ok) {
      setError(result.error || 'Your message could not be sent.');
      return;
    }
    const conversationToken = result.conversationToken as string | undefined;
    if (!conversationToken) {
      setError('The conversation was saved, but a secure reply link could not be created.');
      return;
    }
    const subject = String(form.get('subject') || '').trim() || null;
    const name = String(form.get('name') || '').trim() || null;
    const nextConversation: PublicConversation = {
      submissionId: result.submissionId,
      subject,
      guestName: name,
      initialMessage: message,
      createdAt: new Date().toISOString(),
      status: 'new',
      messages: result.automaticReply ? [{
        id: `automatic-${result.submissionId}`,
        senderType: 'owner',
        content: result.automaticReply,
        createdAt: new Date().toISOString(),
      }] : [],
    };
    setConversation(nextConversation);
    setRememberedConversations(rememberPublicDm({
      username: config.username || username,
      submissionId: result.submissionId,
      token: conversationToken,
      recipientName: config.displayName,
      conversationTitle: subject || config.title,
      avatarUrl: config.logoUrl || config.avatarUrl,
      accentColor: config.accentColor,
      updatedAt: nextConversation.messages.at(-1)?.createdAt || nextConversation.createdAt,
    }));
    navigate(
      `/pd/${encodeURIComponent(username)}?conversation=${encodeURIComponent(result.submissionId)}&token=${encodeURIComponent(conversationToken)}`,
      { replace: true },
    );
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleThreadReply = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const content = threadReply.trim();
    if (!content || sendingReply || !conversation) return;
    setSendingReply(true);
    setError('');
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: {
        ...await authHeaders(),
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ message: content }),
    });
    const result = await response.json().catch(() => ({}));
    setSendingReply(false);
    if (!response.ok) {
      setError(result.error || 'Your reply could not be sent.');
      return;
    }
    setThreadReply('');
    setConversation((current) => current ? {
      ...current,
      messages: [...current.messages, result.message as ConversationMessage],
    } : current);
  };

  const openRememberedConversation = (item: RememberedPublicDm) => {
    setError('');
    navigate(publicDmConversationPath(item));
  };

  if (loading) {
    return (
      <div className="flex min-h-[100dvh] items-center justify-center bg-[#f5f5f2] text-gray-500">
        <Loader2 className="mr-2 h-5 w-5 animate-spin" /> Loading public inbox...
      </div>
    );
  }

  if (receiptStatus) {
    const wasRead = receiptStatus.status === 'read' || Boolean(receiptStatus.readAt);
    return (
      <div className="flex min-h-[100dvh] items-center justify-center bg-[#f5f5f2] p-5">
        <SEO title="Public DM delivery status" description="View the status of your public DM." url={`/pd/${username}`} noIndex />
        <div className="w-full max-w-md rounded-[28px] border border-black/10 bg-white p-8 text-center shadow-xl shadow-black/5">
          <CheckCircle2 className={`mx-auto h-10 w-10 ${wasRead ? 'text-emerald-500' : 'text-indigo-500'}`} />
          <h1 className="mt-5 text-2xl font-bold">{wasRead ? 'Message read' : 'Message delivered'}</h1>
          <p className="mt-3 text-sm leading-6 text-gray-500">
            {wasRead && receiptStatus.readAt
              ? `Read on ${new Date(receiptStatus.readAt).toLocaleString('en-US')}.`
              : `Securely delivered on ${new Date(receiptStatus.createdAt).toLocaleString('en-US')}.`}
          </p>
        </div>
      </div>
    );
  }

  if (!config) {
    return (
      <div className="flex min-h-[100dvh] items-center justify-center bg-[#f5f5f2] p-5">
        <SEO title="Public DM" description="Send a secure message through Wersee." url={`/pd/${username}`} noIndex />
        <div className="w-full max-w-md rounded-[28px] border border-black/10 bg-white p-8 text-center shadow-xl shadow-black/5">
          {requiresAuthentication ? <LockKeyhole className="mx-auto h-9 w-9 text-gray-700" /> : <AlertCircle className="mx-auto h-9 w-9 text-red-500" />}
          <h1 className="mt-5 text-2xl font-bold text-[#171717]">{requiresAuthentication ? 'Sign in to send a message' : 'Inbox unavailable'}</h1>
          <p className="mt-3 text-sm leading-6 text-gray-500">{error}</p>
          {requiresAuthentication && (
            <button type="button" onClick={() => navigate(`/auth?redirect=${encodeURIComponent(window.location.pathname + window.location.search)}`)} className="mt-6 inline-flex items-center gap-2 rounded-xl bg-black px-5 py-3 text-sm font-bold text-white">
              Sign in to Wersee <ArrowRight className="h-4 w-4" />
            </button>
          )}
        </div>
      </div>
    );
  }

  const brandImage = config.logoUrl || config.avatarUrl;
  const activeConversationId = conversation
    ? `${(config.username || username).replace(/^@/, '').toLowerCase()}:${conversation.submissionId}`
    : null;

  return (
    <div className={`${conversation ? 'h-[100dvh] overflow-hidden' : 'min-h-[100dvh]'} bg-[#07080c] text-white`}>
      <SEO title={`${config.title} - ${config.displayName}`} description={config.description} url={`/pd/${username}`} noIndex />
      <div className={`${conversation ? 'flex h-full min-h-0 flex-col overflow-hidden' : 'flex min-h-[100dvh] flex-col'} w-full md:grid md:grid-cols-[340px_minmax(0,1fr)]`}>
        <PublicDmHistoryRail
          accentColor={config.accentColor}
          currentDisplayName={config.displayName}
          currentDescription={config.description}
          currentTitle={config.title}
          brandImage={brandImage}
          conversations={rememberedConversations}
          activeConversationId={activeConversationId}
          onSelect={openRememberedConversation}
        />

        <motion.main
          initial={{ opacity: 0, y: 24 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.08, ease: [0.22, 1, 0.36, 1] }}
          className={`relative min-h-0 min-w-0 flex-1 overflow-hidden ${
            conversation
              ? 'h-full bg-[#08090d] md:p-5 lg:p-7'
              : 'overflow-y-auto bg-[#08090d] px-4 py-8 sm:px-6 md:min-h-[100dvh] md:px-10 md:py-12 lg:px-14'
          }`}
        >
          <div className="pointer-events-none absolute inset-0 overflow-hidden">
            <motion.div
              className="absolute -right-24 top-[8%] h-[420px] w-[420px] rounded-full opacity-[0.13] blur-[90px]"
              style={{ backgroundColor: config.accentColor }}
              animate={{ y: [0, 36, 0], scale: [1, 1.08, 1] }}
              transition={{ duration: 14, repeat: Infinity, ease: 'easeInOut' }}
            />
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_42%_0%,rgba(255,255,255,0.055),transparent_32%)]" />
          </div>

          <div className={`relative mx-auto w-full ${conversation ? 'h-full max-w-none' : 'max-w-4xl'}`}>
            {conversation ? (
              <motion.section
                initial={{ opacity: 0, scale: 0.97 }}
                animate={{ opacity: 1, scale: 1 }}
                className="flex h-full min-h-0 w-full flex-col overflow-hidden bg-[#0d0f14] shadow-2xl shadow-black/30 md:rounded-[30px] md:border md:border-white/[0.08]"
              >
                <header className="flex min-h-[70px] shrink-0 items-center gap-3 border-b border-white/[0.07] bg-[#0d0f14]/90 px-4 py-3 backdrop-blur-2xl md:min-h-[78px] md:px-6">
                  <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl text-white shadow-lg shadow-black/25 md:h-12 md:w-12" style={{ backgroundColor: config.accentColor }}>
                    {brandImage ? <img src={brandImage} alt="" className="h-full w-full rounded-2xl object-cover" /> : <MessageCircle className="h-5 w-5" />}
                  </div>
                  <div className="min-w-0 flex-1">
                    <h2 className="truncate text-[15px] font-bold tracking-[-0.01em] text-white md:text-base">{conversation.subject || config.title}</h2>
                    <p className="mt-0.5 flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-[0.08em] text-emerald-400/75 md:text-[11px]">
                      <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 shadow-[0_0_10px_rgba(52,211,153,0.9)]" />
                      Secure conversation with {config.displayName}
                    </p>
                  </div>
                  <div className="hidden items-center gap-1.5 rounded-full border border-white/[0.07] bg-white/[0.045] px-3 py-1.5 text-[10px] font-bold text-white/45 sm:flex">
                    <CheckCircle2 className="h-3.5 w-3.5 text-emerald-400" /> Delivered
                  </div>
                </header>

                <div className="relative flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto bg-[radial-gradient(circle_at_50%_-10%,rgba(255,255,255,0.045),transparent_35%)] px-3 py-5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden md:gap-5 md:px-7 md:py-7">
                  <div className="mx-auto flex max-w-[90%] items-center gap-2 rounded-full border border-white/[0.07] bg-white/[0.035] px-3 py-1.5 text-center text-[10px] font-medium text-white/35">
                    <Sparkles className="h-3.5 w-3.5" style={{ color: config.accentColor }} />
                    {config.thankYouMessage}
                  </div>

                  <div className="mx-auto w-full max-w-5xl">
                    <div className="flex justify-end">
                      <div className="max-w-[88%] rounded-[24px] rounded-br-[7px] px-4 py-3 text-sm leading-6 text-white shadow-lg shadow-black/10 md:max-w-[72%]" style={{ backgroundColor: config.accentColor }}>
                        <p className="whitespace-pre-wrap">{conversation.initialMessage}</p>
                        <span className="mt-1.5 block text-right text-[10px] text-white/60">
                          {new Date(conversation.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </span>
                      </div>
                    </div>

                    <AnimatePresence initial={false}>
                      {conversation.messages.map((item) => {
                        const fromGuest = item.senderType === 'guest';
                        return (
                          <motion.div
                            key={item.id}
                            initial={{ opacity: 0, y: 12, scale: 0.98 }}
                            animate={{ opacity: 1, y: 0, scale: 1 }}
                            className={`mt-4 flex ${fromGuest ? 'justify-end' : 'justify-start'}`}
                          >
                            <div
                              className={`max-w-[88%] rounded-[24px] px-4 py-3 text-sm leading-6 shadow-lg shadow-black/10 md:max-w-[72%] ${
                                fromGuest
                                  ? 'rounded-br-[7px] text-white'
                                  : 'rounded-bl-[7px] border border-white/[0.07] bg-white/[0.065] text-white/80 backdrop-blur-xl'
                              }`}
                              style={fromGuest ? { backgroundColor: config.accentColor } : undefined}
                            >
                              {!fromGuest && <span className="mb-1 block text-[10px] font-bold uppercase tracking-[0.08em] text-white/35">{config.displayName}</span>}
                              <p className="whitespace-pre-wrap">{item.content}</p>
                              <span className={`mt-1.5 block text-right text-[10px] ${fromGuest ? 'text-white/60' : 'text-white/25'}`}>
                                {new Date(item.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                              </span>
                            </div>
                          </motion.div>
                        );
                      })}
                    </AnimatePresence>
                    <div ref={messagesEndRef} />
                  </div>
                </div>

                <form onSubmit={handleThreadReply} className="shrink-0 border-t border-white/[0.07] bg-[#0d0f14]/95 px-3 pb-[max(12px,env(safe-area-inset-bottom))] pt-3 backdrop-blur-2xl md:px-6 md:pb-5 md:pt-4">
                  {error && (
                    <div className="mx-auto mb-3 flex max-w-5xl items-start gap-2 rounded-xl border border-red-400/15 bg-red-500/10 p-3 text-xs text-red-200" role="alert">
                      <AlertCircle className="mt-0.5 h-3.5 w-3.5 shrink-0" />{error}
                    </div>
                  )}
                  <div className="mx-auto w-full max-w-5xl">
                    <div className="flex items-end gap-2 rounded-[28px] border border-white/10 bg-white/[0.065] p-1.5 pl-4 shadow-[0_18px_70px_rgba(0,0,0,0.3)] transition focus-within:border-white/20 focus-within:bg-white/[0.085]">
                      <textarea
                        value={threadReply}
                        onChange={(event) => setThreadReply(event.target.value.slice(0, 3000))}
                        onKeyDown={(event) => {
                          if (event.key === 'Enter' && !event.shiftKey) {
                            event.preventDefault();
                            event.currentTarget.form?.requestSubmit();
                          }
                        }}
                        rows={1}
                        placeholder={`Message ${config.displayName}`}
                        className="max-h-32 min-h-11 min-w-0 flex-1 resize-none bg-transparent py-2.5 text-[15px] leading-6 text-white outline-none placeholder:text-white/25"
                      />
                      <motion.button
                        type="submit"
                        whileTap={{ scale: 0.9 }}
                        disabled={!threadReply.trim() || sendingReply}
                        className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full text-white shadow-lg transition disabled:cursor-not-allowed disabled:opacity-30"
                        style={{ backgroundColor: config.accentColor }}
                        aria-label="Send reply"
                      >
                        {sendingReply ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
                      </motion.button>
                    </div>
                    <p className="mt-2 hidden text-center text-[9px] font-semibold uppercase tracking-[0.12em] text-white/20 sm:block">
                      Private reply · Enter to send · Shift + Enter for a new line
                    </p>
                  </div>
                </form>
              </motion.section>
            ) : (
              <motion.form
                onSubmit={handleSubmit}
                initial={{ opacity: 0, y: 18 }}
                animate={{ opacity: 1, y: 0 }}
                className="relative space-y-6 overflow-hidden rounded-[30px] border border-white/[0.08] bg-white/[0.035] p-5 shadow-[0_30px_100px_rgba(0,0,0,0.32)] backdrop-blur-2xl sm:p-7 md:rounded-[36px] md:p-9"
              >
                <div className="pointer-events-none absolute -right-24 -top-28 h-72 w-72 rounded-full opacity-15 blur-[70px]" style={{ backgroundColor: config.accentColor }} />
                <div className="relative">
                  <div className="mb-7 flex items-center gap-3">
                    {brandImage ? (
                      <img src={brandImage} alt="" className="h-12 w-12 rounded-2xl border border-white/10 object-cover shadow-lg" />
                    ) : (
                      <span className="flex h-12 w-12 items-center justify-center rounded-2xl text-sm font-black text-white" style={{ backgroundColor: config.accentColor }}>
                        {config.displayName.slice(0, 1).toUpperCase()}
                      </span>
                    )}
                    <span className="min-w-0">
                      <span className="block text-[10px] font-black uppercase tracking-[0.18em] text-white/30">New Public DM</span>
                      <span className="mt-0.5 block truncate text-sm font-bold text-white">{config.displayName}</span>
                    </span>
                    <span className="ml-auto flex items-center gap-1.5 rounded-full border border-emerald-400/10 bg-emerald-400/[0.06] px-2.5 py-1.5 text-[9px] font-bold uppercase tracking-[0.08em] text-emerald-300/65">
                      <span className="h-1.5 w-1.5 rounded-full bg-emerald-400" /> Private
                    </span>
                  </div>
                  <p className="text-[10px] font-black uppercase tracking-[0.18em] text-white/25">Start a conversation</p>
                  <h1 className="mt-3 max-w-2xl text-3xl font-bold leading-[1.05] tracking-[-0.045em] text-white sm:text-4xl md:text-5xl">
                    {config.title}
                  </h1>
                  <p className="mt-4 max-w-2xl text-sm leading-6 text-white/40 md:text-base md:leading-7">{config.description}</p>
                </div>

                {config.presetTopics?.length > 0 && (
                  <div className="relative flex flex-wrap gap-2">
                    {config.presetTopics.map((item) => (
                      <button
                        type="button"
                        key={item}
                        onClick={() => setTopic(item)}
                        className={`rounded-full border px-3.5 py-2 text-xs font-semibold transition ${
                          topic === item
                            ? 'border-transparent text-white shadow-lg'
                            : 'border-white/[0.08] bg-white/[0.035] text-white/40 hover:border-white/15 hover:text-white/70'
                        }`}
                        style={topic === item ? { backgroundColor: config.accentColor } : undefined}
                      >
                        {item}
                      </button>
                    ))}
                  </div>
                )}

                <div className="relative grid gap-4 md:grid-cols-2">
                  <label className="block">
                    <span className="mb-2 block text-xs font-semibold text-white/55">Name {config.requirements.name && '*'}</span>
                    <input name="name" required={config.requirements.name} autoComplete="name" className={inputClass} />
                  </label>
                  <label className="block">
                    <span className="mb-2 block text-xs font-semibold text-white/55">Email address <span className="font-normal text-white/25">(optional)</span></span>
                    <input name="email" type="email" autoComplete="email" className={inputClass} />
                  </label>
                  {config.requirements.company !== 'hidden' && (
                    <label className="block">
                      <span className="mb-2 block text-xs font-semibold text-white/55">Company name {config.requirements.company === 'required' && '*'}</span>
                      <input name="companyName" required={config.requirements.company === 'required'} autoComplete="organization" className={inputClass} />
                    </label>
                  )}
                  {config.requirements.website && (
                    <label className="block">
                      <span className="mb-2 block text-xs font-semibold text-white/55">Website or social media link</span>
                      <input name="websiteUrl" type="url" placeholder="https://..." className={inputClass} />
                    </label>
                  )}
                </div>

                {config.requirements.subject && (
                  <label className="relative block">
                    <span className="mb-2 block text-xs font-semibold text-white/55">Subject *</span>
                    <input name="subject" required className={inputClass} />
                  </label>
                )}

                {config.requirements.customQuestions.map((question) => (
                  <label key={question.id} className="relative block">
                    <span className="mb-2 block text-xs font-semibold text-white/55">{question.label} {question.required && '*'}</span>
                    <input
                      required={question.required}
                      value={customAnswers[question.id] || ''}
                      onChange={(event) => setCustomAnswers((current) => ({ ...current, [question.id]: event.target.value }))}
                      className={inputClass}
                    />
                  </label>
                ))}

                <label className="relative block rounded-[24px] border border-white/10 bg-black/20 p-2 transition focus-within:border-white/20 focus-within:bg-black/30">
                  <span className="flex items-center justify-between px-3 pb-2 pt-2 text-xs font-semibold text-white/55">
                    Message *
                    <span className="text-[10px] font-normal text-white/25">{message.length}/{config.requirements.maximumLength}</span>
                  </span>
                  <textarea
                    required
                    value={message}
                    onChange={(event) => setMessage(event.target.value.slice(0, config.requirements.maximumLength))}
                    className="min-h-48 w-full resize-y rounded-[18px] border-0 bg-white/[0.045] px-4 py-4 text-[15px] leading-7 text-white outline-none placeholder:text-white/20"
                    placeholder={`Write something meaningful to ${config.displayName}...`}
                  />
                </label>

                {config.requirements.attachments && (
                  <div className="relative">
                    <label className="flex cursor-pointer items-center justify-center gap-2 rounded-2xl border border-dashed border-white/10 bg-white/[0.025] px-4 py-5 text-sm font-semibold text-white/40 transition hover:border-white/20 hover:text-white/65">
                      <FileUp className="h-5 w-5" />Choose attachments (max. 3 x 5 MB)
                      <input type="file" multiple className="sr-only" accept=".jpg,.jpeg,.png,.webp,.pdf,.txt,.doc,.docx" onChange={(event) => addFiles(event.target.files)} />
                    </label>
                    {files.length > 0 && (
                      <div className="mt-2 space-y-2">
                        {files.map((file, index) => (
                          <div key={`${file.name}-${index}`} className="flex items-center gap-3 rounded-xl border border-white/[0.07] bg-white/[0.04] px-3 py-2 text-sm text-white/60">
                            <span className="min-w-0 flex-1 truncate">{file.name}</span>
                            <button type="button" onClick={() => setFiles((current) => current.filter((_, fileIndex) => fileIndex !== index))} className="text-white/30 hover:text-red-300"><X className="h-4 w-4" /></button>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                )}

                {config.captcha.enabled && (
                  <div className="relative">
                    {!config.captcha.available ? (
                      <div className="rounded-xl border border-amber-300/20 bg-amber-400/10 p-3 text-sm text-amber-100">The recipient enabled CAPTCHA, but it has not been configured on the server yet.</div>
                    ) : (
                      <div ref={captchaContainerRef} />
                    )}
                  </div>
                )}

                <label className="relative flex items-start gap-3 rounded-2xl border border-white/[0.07] bg-white/[0.035] p-4 text-sm leading-6 text-white/40">
                  <input name="consent" type="checkbox" required className="mt-1 accent-indigo-500" />
                  <span>{config.consentMessage}</span>
                </label>

                {error && (
                  <div className="relative flex items-start gap-2 rounded-2xl border border-red-400/15 bg-red-500/10 p-4 text-sm text-red-200" role="alert">
                    <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />{error}
                  </div>
                )}

                <motion.button
                  type="submit"
                  whileTap={{ scale: 0.985 }}
                  disabled={submitting || config.captcha.enabled && (!config.captcha.available || !captchaToken)}
                  className="relative flex w-full items-center justify-center gap-2 overflow-hidden rounded-[20px] px-5 py-4 text-base font-bold text-white shadow-[0_18px_55px_rgba(0,0,0,0.32)] transition hover:-translate-y-0.5 disabled:cursor-not-allowed disabled:opacity-40"
                  style={{ background: `linear-gradient(135deg, ${config.accentColor}, color-mix(in srgb, ${config.accentColor} 62%, #ffffff))` }}
                >
                  {submitting ? <Loader2 className="h-5 w-5 animate-spin" /> : <MessageCircle className="h-5 w-5" />}
                  Send message securely
                  <ArrowRight className="h-4 w-4" />
                </motion.button>

                <div className="relative flex items-center justify-center gap-2 text-[10px] text-white/20">
                  <ShieldCheck className="h-3.5 w-3.5" /> IP addresses are not visible to the recipient.
                </div>
              </motion.form>
            )}
          </div>
        </motion.main>
      </div>
    </div>
  );
};
