import { safeLocalStorage, type BrowserStorageLike } from './browserStorage';

const STORAGE_KEY = 'wersee:public-dm-conversations:v1';
const MAX_REMEMBERED_CONVERSATIONS = 20;
const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const USERNAME_PATTERN = /^[a-z0-9._-]{1,80}$/i;
const HEX_COLOR_PATTERN = /^#[0-9a-f]{6}$/i;

export type RememberedPublicDm = {
  id: string;
  username: string;
  submissionId: string;
  token: string;
  recipientName: string;
  conversationTitle: string;
  avatarUrl: string | null;
  accentColor: string;
  updatedAt: string;
};

type RememberPublicDmInput = Omit<RememberedPublicDm, 'id'>;

const cleanText = (value: unknown, maximum: number) => (
  typeof value === 'string' ? value.trim().slice(0, maximum) : ''
);

const cleanAvatarUrl = (value: unknown) => {
  if (typeof value !== 'string' || value.length > 1_000) return null;
  try {
    const parsed = new URL(value);
    return parsed.protocol === 'https:' || parsed.protocol === 'http:' ? parsed.href : null;
  } catch {
    return null;
  }
};

const normalizeEntry = (value: unknown): RememberedPublicDm | null => {
  if (!value || typeof value !== 'object') return null;
  const source = value as Partial<RememberedPublicDm>;
  const username = cleanText(source.username, 80).replace(/^@/, '').toLowerCase();
  const submissionId = cleanText(source.submissionId, 64);
  const token = cleanText(source.token, 512);
  const updatedAt = cleanText(source.updatedAt, 40);
  if (
    !USERNAME_PATTERN.test(username)
    || !UUID_PATTERN.test(submissionId)
    || token.length < 24
    || !Number.isFinite(Date.parse(updatedAt))
  ) {
    return null;
  }

  return {
    id: `${username}:${submissionId}`,
    username,
    submissionId,
    token,
    recipientName: cleanText(source.recipientName, 100) || `@${username}`,
    conversationTitle: cleanText(source.conversationTitle, 160) || 'Public DM',
    avatarUrl: cleanAvatarUrl(source.avatarUrl),
    accentColor: HEX_COLOR_PATTERN.test(cleanText(source.accentColor, 7))
      ? String(source.accentColor)
      : '#6366F1',
    updatedAt: new Date(updatedAt).toISOString(),
  };
};

const writeHistory = (storage: BrowserStorageLike, entries: RememberedPublicDm[]) => {
  storage.setItem(STORAGE_KEY, JSON.stringify(entries.slice(0, MAX_REMEMBERED_CONVERSATIONS)));
};

export const loadPublicDmHistory = (
  storage: BrowserStorageLike = safeLocalStorage,
): RememberedPublicDm[] => {
  try {
    const parsed = JSON.parse(storage.getItem(STORAGE_KEY) || '[]');
    if (!Array.isArray(parsed)) return [];
    const unique = new Map<string, RememberedPublicDm>();
    parsed.forEach((value) => {
      const entry = normalizeEntry(value);
      if (entry && !unique.has(entry.id)) unique.set(entry.id, entry);
    });
    return [...unique.values()]
      .sort((a, b) => Date.parse(b.updatedAt) - Date.parse(a.updatedAt))
      .slice(0, MAX_REMEMBERED_CONVERSATIONS);
  } catch {
    return [];
  }
};

export const rememberPublicDm = (
  input: RememberPublicDmInput,
  storage: BrowserStorageLike = safeLocalStorage,
) => {
  const entry = normalizeEntry({ ...input, id: `${input.username}:${input.submissionId}` });
  if (!entry) return loadPublicDmHistory(storage);
  const next = [
    entry,
    ...loadPublicDmHistory(storage).filter((item) => item.id !== entry.id),
  ].slice(0, MAX_REMEMBERED_CONVERSATIONS);
  writeHistory(storage, next);
  return next;
};

export const forgetPublicDm = (
  username: string,
  submissionId: string,
  storage: BrowserStorageLike = safeLocalStorage,
) => {
  const id = `${username.replace(/^@/, '').toLowerCase()}:${submissionId}`;
  const next = loadPublicDmHistory(storage).filter((item) => item.id !== id);
  writeHistory(storage, next);
  return next;
};

export const publicDmConversationPath = (entry: RememberedPublicDm) => (
  `/pd/${encodeURIComponent(entry.username)}?conversation=${encodeURIComponent(entry.submissionId)}&token=${encodeURIComponent(entry.token)}`
);

