import { memo, type CSSProperties } from 'react';
import { Clock3, MessageCircle, MessagesSquare, ShieldCheck } from 'lucide-react';
import { motion } from 'motion/react';
import type { RememberedPublicDm } from '../../lib/publicDmHistory';

type Props = {
  accentColor: string;
  currentDisplayName: string;
  currentDescription: string;
  currentTitle: string;
  brandImage: string | null;
  conversations: RememberedPublicDm[];
  activeConversationId: string | null;
  onSelect: (conversation: RememberedPublicDm) => void;
};

const initials = (value: string) => value
  .split(/\s+/)
  .filter(Boolean)
  .slice(0, 2)
  .map((part) => part[0]?.toUpperCase())
  .join('') || 'PD';

export const PublicDmHistoryRail = memo(function PublicDmHistoryRail({
  accentColor,
  currentDisplayName,
  currentDescription,
  currentTitle,
  brandImage,
  conversations,
  activeConversationId,
  onSelect,
}: Props) {
  return (
    <motion.aside
      initial={{ opacity: 0, x: -28 }}
      animate={{ opacity: 1, x: 0 }}
      transition={{ duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
      className="relative z-10 flex shrink-0 flex-col overflow-hidden border-b border-white/10 bg-[#090a0f] text-white md:h-[100dvh] md:border-b-0 md:border-r"
      style={{ '--public-dm-accent': accentColor } as CSSProperties}
    >
      <div className="pointer-events-none absolute inset-0 overflow-hidden">
        <motion.div
          className="absolute -right-20 -top-24 h-64 w-64 rounded-full opacity-25 blur-3xl"
          style={{ backgroundColor: accentColor }}
          animate={{ x: [0, -18, 0], y: [0, 22, 0], scale: [1, 1.1, 1] }}
          transition={{ duration: 11, repeat: Infinity, ease: 'easeInOut' }}
        />
        <div className="absolute inset-0 bg-[linear-gradient(145deg,rgba(255,255,255,0.055),transparent_42%)]" />
      </div>

      <div className="relative flex items-center gap-3 px-4 pb-3 pt-[max(14px,env(safe-area-inset-top))] md:px-5 md:pb-5 md:pt-6">
        <span className="flex h-9 w-9 items-center justify-center rounded-2xl border border-white/10 bg-white/[0.06]">
          <MessagesSquare className="h-4 w-4" />
        </span>
        <span className="min-w-0">
          <span className="block text-[10px] font-black uppercase tracking-[0.18em] text-white/40">Wersee</span>
          <span className="block truncate text-sm font-bold">Public conversations</span>
        </span>
        <span className="ml-auto rounded-full border border-white/10 bg-white/[0.05] px-2.5 py-1 text-[10px] font-bold text-white/55">
          {conversations.length}
        </span>
      </div>

      <div className="relative hidden px-5 md:block">
        <div className="rounded-[24px] border border-white/10 bg-white/[0.045] p-4 shadow-2xl shadow-black/20">
          <div className="flex items-center gap-3">
            {brandImage ? (
              <img src={brandImage} alt="" className="h-12 w-12 rounded-2xl border border-white/10 object-cover" />
            ) : (
              <span className="flex h-12 w-12 items-center justify-center rounded-2xl text-xs font-black text-white" style={{ backgroundColor: accentColor }}>
                {initials(currentDisplayName)}
              </span>
            )}
            <span className="min-w-0">
              <span className="block truncate text-sm font-bold">{currentDisplayName}</span>
              <span className="mt-0.5 block truncate text-[11px] text-white/40">{currentTitle}</span>
            </span>
          </div>
          <p className="mt-3 line-clamp-2 text-xs leading-5 text-white/45">{currentDescription}</p>
        </div>
      </div>

      <div className="relative min-h-0 flex-1 px-3 pb-3 md:mt-5 md:px-3 md:pb-5">
        {conversations.length > 0 ? (
          <>
            <div className="mb-2 hidden items-center justify-between px-2 md:flex">
              <span className="text-[10px] font-black uppercase tracking-[0.16em] text-white/30">Recent PDs</span>
              <span className="text-[10px] text-white/25">Saved on this device</span>
            </div>
            <div className="flex snap-x snap-mandatory gap-2 overflow-x-auto pb-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden md:h-full md:flex-col md:overflow-x-hidden md:overflow-y-auto md:pb-0">
              {conversations.map((item) => {
                const active = item.id === activeConversationId;
                return (
                  <button
                    type="button"
                    key={item.id}
                    onClick={() => onSelect(item)}
                    className={`group relative flex min-w-[220px] snap-start items-center gap-3 overflow-hidden rounded-[20px] border p-3 text-left transition-all active:scale-[0.985] md:min-w-0 md:w-full ${
                      active
                        ? 'border-white/20 bg-white/[0.11] shadow-lg shadow-black/15'
                        : 'border-white/[0.055] bg-white/[0.025] hover:border-white/10 hover:bg-white/[0.055]'
                    }`}
                    aria-current={active ? 'page' : undefined}
                  >
                    {active && <span className="absolute bottom-2 left-0 top-2 w-0.5 rounded-full" style={{ backgroundColor: item.accentColor }} />}
                    {item.avatarUrl ? (
                      <img src={item.avatarUrl} alt="" className="h-11 w-11 shrink-0 rounded-2xl object-cover" />
                    ) : (
                      <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl text-[10px] font-black text-white" style={{ backgroundColor: item.accentColor }}>
                        {initials(item.recipientName)}
                      </span>
                    )}
                    <span className="min-w-0 flex-1">
                      <span className="block truncate text-[13px] font-bold text-white">{item.recipientName}</span>
                      <span className="mt-0.5 block truncate text-[11px] text-white/40">{item.conversationTitle}</span>
                      <span className="mt-1 flex items-center gap-1 text-[9px] font-semibold uppercase tracking-[0.08em] text-white/25">
                        <Clock3 className="h-2.5 w-2.5" />
                        {new Date(item.updatedAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                      </span>
                    </span>
                    <MessageCircle className={`h-4 w-4 shrink-0 ${active ? 'text-white' : 'text-white/20 group-hover:text-white/45'}`} />
                  </button>
                );
              })}
            </div>
          </>
        ) : (
          <div className="hidden h-full flex-col justify-end px-3 pb-2 md:flex">
            <p className="text-3xl font-bold leading-tight tracking-[-0.04em]">{currentTitle}</p>
            <p className="mt-3 text-sm leading-6 text-white/45">{currentDescription}</p>
          </div>
        )}
      </div>

      <div className="relative hidden items-center gap-2 border-t border-white/[0.06] px-5 py-4 text-[10px] text-white/30 md:flex">
        <ShieldCheck className="h-3.5 w-3.5" />
        Conversation links stay private on this device.
      </div>
    </motion.aside>
  );
});
